package lockfile

import (
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/crossben/safe-install/internal/ecosystem"
)

// Real lockfiles of one project (requests, flask==3.0.3; pytest as dev),
// generated by uv 0.12, Poetry 2.5, Pipenv and `uv export`.
func TestPythonLockfiles(t *testing.T) {
	for _, c := range []struct {
		file     string
		format   Format
		packages int
		devKnown bool
	}{
		{"uv/uv.lock", UV, 18, true},
		{"poetry/poetry.lock", Poetry, 18, true},
		{"pipenv/Pipfile.lock", Pipenv, 17, true}, // colorama is Windows-only and not locked here
		{"pip/requirements.txt", Requirements, 18, false},
	} {
		g, err := LoadFile(filepath.Join("testdata/python", c.file))
		if err != nil {
			t.Fatalf("%s: %v", c.file, err)
		}
		if g.Format != c.format || len(g.Packages) != c.packages {
			t.Errorf("%s: format %s, %d packages", c.file, g.Format, len(g.Packages))
		}
		var direct []string
		for _, p := range g.Sorted() {
			if p.Ecosystem != ecosystem.PyPI {
				t.Errorf("%s: %s ecosystem %q", c.file, p.ID, p.Ecosystem)
			}
			if len(p.Files) == 0 {
				t.Errorf("%s: %s has no file hashes", c.file, p.ID)
			}
			for _, f := range p.Files {
				if !strings.HasPrefix(f.Hash, "sha256:") {
					t.Errorf("%s: %s hash %q", c.file, p.ID, f.Hash)
				}
			}
			if p.Direct {
				direct = append(direct, p.ID)
			}
		}
		if want := []string{"flask@3.0.3", "pytest@9.1.1", "requests@2.34.2"}; !slices.Equal(direct, want) {
			t.Errorf("%s: direct = %v, want %v", c.file, direct, want)
		}
		if c.devKnown {
			if !g.Packages["pytest@9.1.1"].Dev || !g.Packages["pluggy@1.6.0"].Dev || g.Packages["werkzeug@3.1.9"].Dev {
				t.Errorf("%s: dev flags wrong", c.file)
			}
		}
		if g.Packages["flask@3.0.3"] == nil || (c.format != Pipenv && !slices.Contains(g.Packages["flask@3.0.3"].Dependencies, "werkzeug@3.1.9")) {
			t.Errorf("%s: flask -> werkzeug edge missing", c.file)
		}
	}
}

func TestUVFileNamesAndSources(t *testing.T) {
	g, err := Parse("uv.lock", []byte(`version = 1
[[package]]
name = "app"
version = "0.1.0"
source = { virtual = "." }
dependencies = [{ name = "Typing_Extensions" }, { name = "mylib" }]

[[package]]
name = "typing-extensions"
version = "4.12.2"
source = { registry = "https://pypi.org/simple" }
wheels = [{ url = "https://files.pythonhosted.org/x/typing_extensions-4.12.2-py3-none-any.whl", hash = "sha256:aa" }]

[[package]]
name = "mylib"
version = "1.0.0"
source = { git = "https://github.com/x/mylib?rev=abc" }
`), t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	te := g.Packages["typing-extensions@4.12.2"]
	if te == nil || !te.Direct || te.Resolved != "https://pypi.org/simple" || te.Files[0].Name != "typing_extensions-4.12.2-py3-none-any.whl" {
		t.Fatalf("typing-extensions = %+v", te)
	}
	if lib := g.Packages["mylib@1.0.0"]; lib == nil || !strings.HasPrefix(lib.Resolved, "git:") {
		t.Fatalf("git source should not look like a registry: %+v", lib)
	}
	if g.Packages["app@0.1.0"] != nil {
		t.Fatal("the project itself is not a package to check")
	}
}

func TestRequirementsTxt(t *testing.T) {
	dir := t.TempDir()
	write := func(name, s string) {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(s), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	write("base.txt", "certifi==2024.8.30 --hash=sha256:cc\n")
	write("requirements.txt", `# hand-written
-r base.txt
--index-url https://pypi.org/simple
-e .
Django==5.1.2 \
    --hash=sha256:aa \
    --hash=sha256:bb
requests[socks]==2.32.3 ; python_version >= "3.8"
flask>=3
    # via something
`)
	g, err := LoadFile(filepath.Join(dir, "requirements.txt"))
	if err != nil {
		t.Fatal(err)
	}
	dj := g.Packages["django@5.1.2"]
	if dj == nil || !dj.Direct || len(dj.Files) != 2 {
		t.Fatalf("django = %+v", dj)
	}
	if r := g.Packages["requests@2.32.3"]; r == nil || !r.Direct {
		t.Fatalf("requests with extras and markers: %+v", r)
	}
	if g.Packages["certifi@2024.8.30"] == nil {
		t.Fatal("-r include not read")
	}
	if f := g.Packages["flask@"]; f == nil {
		t.Fatal("an unpinned requirement is listed (version unknown, so not checked)")
	}

	if _, err := Parse("requirements.txt", []byte("-r ../../etc/passwd\n"), dir); err == nil || !strings.Contains(err.Error(), "outside the project") {
		t.Fatalf("include outside the project: %v", err)
	}
	write("loop.txt", "-r loop.txt\nsix==1.16.0\n")
	if g, err := Parse("requirements.txt", []byte("-r loop.txt\n"), dir); err != nil || g.Packages["six@1.16.0"] == nil {
		t.Fatalf("self-including file: %v", err)
	}
}

func TestPythonLockfilesRejectGarbage(t *testing.T) {
	for name, data := range map[string]string{
		"uv.lock":      "version = 2\n",
		"poetry.lock":  "[[package]\nname=",
		"Pipfile.lock": "{",
	} {
		if _, err := Parse(name, []byte(data), t.TempDir()); err == nil {
			t.Errorf("%s: accepted %q", name, data)
		}
	}
	if _, err := Parse("uv.lock", []byte("version = 1\n[[package]]\nname = 1\n"), t.TempDir()); err == nil {
		t.Error("uv.lock with a non-string name accepted")
	}
}

func TestFindFor(t *testing.T) {
	dir := t.TempDir()
	for _, f := range []string{"package-lock.json", "requirements.txt", "uv.lock"} {
		if err := os.WriteFile(filepath.Join(dir, f), nil, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	if p, _ := FindFor(dir, ecosystem.PyPI); filepath.Base(p) != "uv.lock" {
		t.Errorf("PyPI: %s, want uv.lock (over requirements.txt)", p)
	}
	if p, _ := FindFor(dir, ecosystem.NPM); filepath.Base(p) != "package-lock.json" {
		t.Errorf("npm: %s", p)
	}
}
